alter function public.save_progress(jsonb,jsonb,integer) rename to save_progress_legacy;
revoke all on function public.save_progress_legacy(jsonb,jsonb,integer) from public,anon,authenticated;
create function public.save_progress(p_state jsonb,p_session jsonb,p_revision integer)
returns jsonb language plpgsql security definer set search_path='' as $$
declare h jsonb; a jsonb; cleaned jsonb:='[]'; answers jsonb; release jsonb; matches boolean; result jsonb; unknown jsonb:='[]';
begin
 if auth.uid() is null or (p_state->>'_owner_id')::uuid is distinct from auth.uid() then raise exception 'Account changed'; end if;
 if octet_length(p_state::text)>5000000 or jsonb_typeof(p_state->'history') is distinct from 'array' or jsonb_array_length(p_state->'history')>10000 then raise exception 'Invalid progress'; end if;
 for h in select * from jsonb_array_elements(p_state->'history') loop
  if jsonb_typeof(h->'answers') is distinct from 'array' then raise exception 'Invalid history'; end if;
  select question_versions into release from private.content_releases where version=h->>'content_version';
  matches:=release is not null and not exists(select 1 from jsonb_array_elements(h->'answers') v left join public.questions q on q.id=(v->>'id')::integer where q.id is null or q.content_version is distinct from release->>q.id::text);
  answers:='[]';
  for a in select * from jsonb_array_elements(h->'answers') loop
   if matches then a:=a||jsonb_build_object('correct',coalesce((a->>'chosen')::integer=(select answer from private.answer_keys where question_id=(a->>'id')::integer),false)); end if;
   answers:=answers||jsonb_build_array(a);
  end loop;
  cleaned:=cleaned||jsonb_build_array(h||jsonb_build_object('answers',answers,'server_graded',false));
 end loop;
 result:=public.save_progress_legacy(p_state||jsonb_build_object('history',cleaned),p_session,p_revision);
 if jsonb_typeof(p_state->'unverified_mistakes')='array' and jsonb_array_length(p_state->'unverified_mistakes')<=246 then
  select coalesce(jsonb_agg(distinct q.id),'[]') into unknown from jsonb_array_elements_text(p_state->'unverified_mistakes') x join public.questions q on q.id=x::integer;
 end if;
 update public.progress_snapshots set state=state||jsonb_build_object('unverified_mistakes',unknown) where user_id=auth.uid();
 return result;
end $$;
revoke all on function public.save_progress(jsonb,jsonb,integer) from public,anon;
grant execute on function public.save_progress(jsonb,jsonb,integer) to authenticated;
commit;
